<?php require 'includes/bootstrap.php';if(me())go('dashboard.php');$error='';$dev='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$email=strtolower(trim($_POST['email']??''));$s=$pdo->prepare('SELECT * FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();$valid=$u&&(!$u['locked_until']||strtotime($u['locked_until'])<time())&&password_verify($_POST['password']??'',$u['password_hash']);if($valid&&$u['verified_at']){$otp=(string)random_int(100000,999999);$hash=hash_hmac('sha256',$otp,$config['app_secret']);$pdo->prepare('UPDATE users SET otp_hash=?,otp_expires=DATE_ADD(NOW(),INTERVAL 10 MINUTE),failed_logins=0 WHERE id=?')->execute([$hash,$u['id']]);$_SESSION['pending_uid']=$u['id'];$sent=send_mail_safe($email,'Your SecureFin login code',"Your one-time code is $otp. It expires in 10 minutes.");audit('password_accepted',(int)$u['id'],$sent?'otp sent':'mail unavailable');if($config['dev_show_tokens'])$dev=$otp;if(!$dev)go('otp.php');}else{if($u){$fails=(int)$u['failed_logins']+1;$lock=$fails>=5?date('Y-m-d H:i:s',time()+900):null;$pdo->prepare('UPDATE users SET failed_logins=?,locked_until=? WHERE id=?')->execute([$fails,$lock,$u['id']]);audit('login_failed',(int)$u['id']);}$error='Login failed, account unverified, or temporarily locked.';}}
$pageTitle='Login';require 'includes/header.php';?><section class="card narrow"><h1>Secure login</h1><?php if($error):?><p class="error"><?=e($error)?></p><?php endif?><?php if($dev):?><p class="notice">Development OTP: <?=e($dev)?> — <a href="otp.php">continue</a></p><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Email<input type="email" name="email" required autocomplete="username"></label><label>Password<input type="password" name="password" required autocomplete="current-password"></label><button class="button">Continue to email code</button></form></section><?php require 'includes/footer.php';?>
